"""Publish a NEW, self-contained materializer comparison runtime archive.

Run only after all timings and documentation writes have finished. This packages
all 127 original runtime artifacts, both exact candidate production trees, the
sanitized OFF/DENSE JFR copies, source snapshots and reproduction metadata. It
reads back every archive member and reconstructs every artifact hash. No Java,
build, network, Git staging, or store copying occurs. Existing outputs are never
replaced. The complete project source/evidence archives are separate products.
"""

from __future__ import annotations

import argparse
import gzip
import hashlib
import io
import json
import os
from pathlib import Path, PurePosixPath
import shutil
import sys
import tarfile
import tempfile

from comparison_runtime_io import (BUNDLE_MANIFEST, FOLLOWUP, ORIGINAL_PROFILES, PROFILES, PROTOCOL, Inventory,
                                   file_hash, json_bytes, member_relative, path_under, portable,
                                   publish_no_replace, require, sha_bytes, tree_digest, verify_experiment,
                                   verify_profile_disclosure)

DERIVED_EXPANSIONS = {
    FOLLOWUP + "/frozen-off/events.jsonl",
    FOLLOWUP + "/frozen-dense/events.jsonl",
    FOLLOWUP + "/frozen-off/events-first-extraction-partial.jsonl",
    FOLLOWUP + "/frozen-dense/events-first-extraction-partial.jsonl",
}
HELPERS = ("bundle-comparison-runtime.py", "rebase-materializer-comparison.py", "comparison_runtime_io.py")


def directories_for(files: dict[str, dict]) -> set[str]:
    result = set()
    for name in files:
        for parent in PurePosixPath(name).parents:
            if parent.as_posix() != ".":
                result.add(parent.as_posix())
    require(not result.intersection(files), "A package file is also the parent of another file")
    return result


def add_member(archive, name: str, mode: int, size: int = 0, stream=None, directory: bool = False) -> None:
    item = tarfile.TarInfo(name)
    item.mode = mode
    item.uid = item.gid = item.mtime = 0
    item.uname = item.gname = ""
    item.type = tarfile.DIRTYPE if directory else tarfile.REGTYPE
    item.size = 0 if directory else size
    archive.addfile(item, stream)


def write_archive(destination: Path, repo: Path, files: dict[str, dict], generated: dict[str, bytes]) -> None:
    directories = directories_for(files)
    with destination.open("xb") as raw:
        with gzip.GzipFile(filename="", mode="wb", fileobj=raw, mtime=0, compresslevel=6) as zipped:
            with tarfile.open(fileobj=zipped, mode="w|", format=tarfile.PAX_FORMAT) as archive:
                for name in sorted(directories, key=PurePosixPath):
                    add_member(archive, name, 0o755, directory=True)
                for name in sorted(files, key=PurePosixPath):
                    record = files[name]
                    if name in generated:
                        add_member(archive, name, record["mode"], record["size"], io.BytesIO(generated[name]))
                    else:
                        with path_under(repo, member_relative(name)).open("rb") as stream:
                            add_member(archive, name, record["mode"], record["size"], stream)


def readback(archive_path: Path, expected: dict[str, dict], artifacts: list[dict]) -> dict:
    directories = directories_for(expected)
    seen = set()
    hashes = {}
    with tarfile.open(archive_path, "r:gz") as archive:
        for member in archive:
            name = portable(member.name.rstrip("/"))
            require(name not in seen, f"Duplicate archive member: {name}")
            seen.add(name)
            require(member.uid == member.gid == member.mtime == 0 and not member.uname and not member.gname,
                    f"Unexpected archive ownership/time metadata: {name}")
            if member.isdir():
                require(name in directories and member.mode == 0o755, f"Unexpected directory: {name}")
                continue
            require(member.isfile() and name in expected, f"Unexpected or non-regular archive member: {name}")
            record = expected[name]
            require(member.size == record["size"] and member.mode == record["mode"], f"Archive size/mode differs: {name}")
            digest = hashlib.sha256()
            with archive.extractfile(member) as stream:
                for block in iter(lambda: stream.read(1024 * 1024), b""):
                    digest.update(block)
            require(digest.hexdigest() == record["sha256"], f"Archive content differs: {name}")
            hashes[name] = {"bytes": member.size, "sha256": digest.hexdigest()}
    require(seen == directories | set(expected), "Archive member coverage differs")
    reconstructed = []
    for artifact in artifacts:
        path = artifact["path"]
        if artifact["kind"] == "file":
            actual = hashes[path]["sha256"]
        else:
            prefix = path + "/"
            children = {name[len(prefix):]: entry for name, entry in hashes.items() if name.startswith(prefix)}
            require(len(children) == artifact["files"], f"Artifact file count differs after readback: {path}")
            actual = tree_digest(children)
        require(actual == artifact["sha256"], f"Artifact hash differs after readback: {path}")
        reconstructed.append({"path": path, "sha256": actual})
    return {"members": len(seen), "fileHashes": len(hashes), "uniqueArtifactHashes": len(reconstructed),
            "artifacts": reconstructed}


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parents[2])
    parser.add_argument("--results", type=Path, required=True, help="Complete preserved comparison output directory")
    parser.add_argument("--output", type=Path, required=True, help="New directory outside the checkout")
    parser.add_argument("--report", action="append", default=[], help="Additional exact text report path relative to repo")
    args = parser.parse_args()
    repo = args.repo.resolve(strict=True)
    output = args.output.parent.resolve(strict=True) / args.output.name
    require(not os.path.lexists(output) and not output.is_relative_to(repo),
            "Runtime publication needs a new directory outside the checkout")
    results = args.results.resolve(strict=True)
    require(results.is_relative_to(repo / FOLLOWUP) and results.is_dir(), "Results must be a follow-up directory")
    inventory = Inventory(repo)
    experiment = verify_experiment(repo, inventory, str(repo))
    require(len(experiment["artifacts"]) == 129, "Expected 127 shared artifacts plus two candidate trees")
    diagnostic = inventory.json(FOLLOWUP + "/protocol.json")
    inventory.add(FOLLOWUP + "/profile-frozen.py", diagnostic["runnerSha256"])
    inventory.add(FOLLOWUP + "/materializer-profile.jfc", diagnostic["profileJfcSha256"])
    for name in HELPERS:
        inventory.add(FOLLOWUP + "/" + name)
    for name in ("freeze-candidate-runtime.py", "ExtractJfr.java", "analyze-profiles.py", "run-result.json",
                 "classpath-manifest-before.json", "classpath-manifest-after.json", "design-review.md"):
        inventory.add(FOLLOWUP + "/" + name)
    # A frozen runtime can be rerun without a checkout or Maven. The original
    # source-hash map still records these exact original driver files.
    for name in ("run-coordinate-experiments.py", "freeze-experiment-classpath.py"):
        inventory.add("result-coordinate-evidence/" + name)
    # Preserve the additive source-map correction history as distinct metadata;
    # only the protocol-selected corrected descriptor is active for validation.
    inventory.add("result-coordinate-evidence/final-validation/source-hashes.json")
    for path in (repo / FOLLOWUP).iterdir():
        if (path.is_file() and not path.is_symlink()
                and path.suffix.lower() in {".py", ".md", ".json", ".java", ".jfc", ".patch", ".txt", ".csv"}
                and path.relative_to(repo).as_posix() != BUNDLE_MANIFEST):
            inventory.add(path.relative_to(repo).as_posix())
    for root in (FOLLOWUP + "/baseline", FOLLOWUP + "/mutation-characterization", FOLLOWUP + "/helper-history",
                 FOLLOWUP + "/delivery-preflight", FOLLOWUP + "/runtimes/candidate1-metadata-corrected",
                 FOLLOWUP + "/frozen-off", FOLLOWUP + "/frozen-dense",
                 results.relative_to(repo).as_posix()):
        inventory.add_text_tree(root, DERIVED_EXPANSIONS)
    omitted = []
    for relative in sorted(DERIVED_EXPANSIONS):
        if (repo / relative).exists():
            record = inventory.add(relative)
            omitted.append(record | {"reason": "Derived JFR event expansion; sanitized delivery recording, exact extractor/analyzer and original-hash provenance are packaged. Historical partial extraction is not a regeneration target."})
            inventory.files.pop(relative)
            # Keep its stat signature so the recorded omission digest is stable.
    inventory.add_text_tree(FOLLOWUP + "/delivery-profiles")
    disclosure_record = verify_profile_disclosure(inventory)
    require(not set(ORIGINAL_PROFILES).intersection(inventory.files), "Private raw JFR must never be archived")
    for relative in args.report:
        data = inventory.read(portable(relative))
        require(b"\0" not in data, f"Binary report: {relative}")
        data.decode("utf-8")
    inventory.assert_stable()
    manifest = {"format": 1, "archivePrefix": "rdf4j", "originalRepository": str(repo),
                "protocolPath": PROTOCOL, "protocolSha256": experiment["protocolSha256"],
                "resultsPath": results.relative_to(repo).as_posix(), "selfContainedRuntime": True,
                "jdkIncluded": False, "storesIncluded": False, "productionSourceSnapshotsIncluded": True,
                "runtimeArtifacts": experiment["artifacts"], "runtimes": experiment["runtimes"],
                "profiles": [inventory.files[path] for path in PROFILES],
                "recordingSanitizationReceipt": disclosure_record,
                "recordingScope": "Sanitized delivery copies only; original raw recording hashes are provenance, and original files remain private.",
                "derivedExpansionsOmitted": omitted,
                "files": [inventory.files[path] for path in sorted(inventory.files)]}
    manifest_bytes = json_bytes(manifest)
    generated_name = "rdf4j/" + BUNDLE_MANIFEST
    files = {entry["path"]: entry for entry in manifest["files"]}
    require(generated_name not in files, "Generated manifest conflicts with an input")
    files[generated_name] = {"path": generated_name, "size": len(manifest_bytes),
                             "sha256": sha_bytes(manifest_bytes), "mode": 0o644}
    staging = Path(tempfile.mkdtemp(prefix=".materializer-runtime-", dir=output.parent))
    published = False
    try:
        archive_name = "rdf4j-materializer-comparison-runtime.tar.gz"
        archive_path = staging / archive_name
        write_archive(archive_path, repo, files, {generated_name: manifest_bytes})
        verified = readback(archive_path, files, experiment["artifacts"])
        (staging / "comparison-runtime-manifest.json").write_bytes(manifest_bytes)
        receipt = {"format": 1, "archive": {"file": archive_name, "bytes": archive_path.stat().st_size,
                                            "sha256": file_hash(archive_path)},
                   "manifestSha256": sha_bytes(manifest_bytes), "archivePrefix": "rdf4j",
                   "selfContainedRuntime": True, "classpaths": {name: 127 for name in experiment["runtimes"]},
                   "candidateProductionTrees": {name: experiment["runtimes"][name]["entries"][1]["sha256"]
                                                 for name in ("candidate1", "candidate1-and-2")},
                   "sanitizedJfrFiles": manifest["profiles"], "archiveReadback": verified,
                   "originalRawJfrFilesIncluded": False,
                   "inputsStable": True, "existingDeliveriesUnmodified": True,
                   "noJavaBuildGitStageOrNetwork": True}
        (staging / "runtime-verification.json").write_bytes(json_bytes(receipt))
        (staging / "README.md").write_text(
            "# Self-contained materializer comparison runtime\n\n"
            "Extract this one archive under a new directory. Its rdf4j/ tree contains all 127 shared original artifacts, "
            "both candidate production trees, sanitized JFR delivery copies, exact source snapshots, and original comparison inputs. "
            "No earlier runtime archive is required. The complete source/evidence archives use the same rdf4j/ prefix.\n\n"
            "Run `python3 rdf4j/result-coordinate-evidence/materializer-followup/rebase-materializer-comparison.py "
            "--java /path/to/jdk-25.0.5+8/bin/java --output /new/reproduction-plan`. This validates all artifact hashes "
            "and writes a new derivative plan; it executes no Java. Original absolute paths and scripts remain unchanged. "
            "The printed command runs a separate reproduction and must be scheduled in a quiet environment.\n\n"
            "The .jfr files are sanitized delivery copies: initial environment, system-property and security-property "
            "events, plus system-process events, have been removed. The included disclosure receipt links "
            "original/sanitized hashes, retained performance-event "
            "equivalence and redacted disclosure checks. Original raw recordings remain private. Large expanded "
            "events.jsonl files are derived intermediates and are omitted with recorded hashes and reasons. "
            "ExtractJfr.java, analyze-profiles.py, recording configuration, sample JSONL, arrival traces and root audits "
            "are retained. No stores, JDK or Maven cache are included.\n",
            encoding="utf-8")
        (staging / "SHA256SUMS").write_text(
            "".join(f"{file_hash(path)}  {path.name}\n" for path in sorted(staging.iterdir())), encoding="ascii")
        inventory.assert_stable()
        publish_no_replace(staging, output)
        published = True
        print(f"Published and read back self-contained comparison runtime: {output}")
    finally:
        if not published:
            shutil.rmtree(staging)


if __name__ == "__main__":
    try:
        main()
    except (OSError, ValueError, KeyError) as error:
        print(f"ERROR: {error}", file=sys.stderr)
        raise SystemExit(1)
